// CloudtainerML rev0029 — Meta-attention mechanism router toy.
// Inspired by Bayesian per-token routing across full/local/linear/spectral attention mechanisms. Symbolic cost/quality phase probe, not a paper reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){ if(c=='"'||c=='\\') o+='\\'; o+=c;} return o+'"';}
struct Regime{string name; double local, global, smooth, sparse, entropy, ood, token_count;};
struct Method{string name; double full, local, linear, spectral, uncertainty, prior_strength, collapse_full, cost; bool oracle=false;};
struct Row{string regime, method; int budget_pct; double quality,cost_frac,budget_over,route_miss,uncertainty_error,collapse_penalty,regret,score,posterior_entropy;};
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0029_META_ATTENTION_ROUTER_SMOKE.json"; vector<Regime> regs={{"smooth_long_context",0.20,0.62,0.92,0.08,0.24,0.10,4096},{"local_dialogue",0.92,0.20,0.40,0.12,0.35,0.08,1024},{"sparse_needle",0.25,0.88,0.28,0.96,0.74,0.18,8192},{"mixed_code",0.50,0.72,0.45,0.45,0.78,0.22,4096},{"ood_spiky",0.36,0.50,0.20,0.70,0.90,0.92,2048},{"redundant_low_entropy",0.64,0.30,0.82,0.12,0.12,0.04,8192}};
 vector<Method> meth={{"always_full",1,0,0,0,0.05,0,1.0,1.0,false},{"always_local",0,1,0,0,0.05,0,0,0.18,false},{"always_linear",0,0,1,0,0.08,0,0,0.26,false},{"always_spectral",0,0,0,1,0.07,0,0,0.24,false},{"deterministic_mlp_router",0.62,0.28,0.10,0.20,0.18,0.0,0.45,0.53,false},{"cost_prior_router",0.28,0.38,0.24,0.30,0.30,0.55,0.14,0.34,false},{"bayesian_dirichlet_router",0.34,0.34,0.22,0.38,0.62,0.75,0.04,0.38,false},{"hard_posterior_router",0.22,0.42,0.28,0.40,0.45,0.70,0.02,0.28,false},{"oracle_mechanism",1,1,1,1,1,1,0,0.32,true}};
 vector<int> budgets={20,32,45,60,80,100}; vector<Row> rows; map<string,int> win, non;
 for(auto&r:regs) for(int bp:budgets){ vector<Row> cand; double budget=bp/100.0; for(auto&m:meth){ double full_need=0.52*r.global+0.42*r.sparse+0.22*r.entropy+0.10*r.ood; double local_need=0.74*r.local+0.08*(1-r.global); double linear_need=0.58*r.smooth+0.18*(1-r.sparse)+0.10*r.global-0.20*r.ood; double spectral_need=0.67*r.smooth+0.18*r.global-0.40*r.sparse-0.25*r.ood; double raw=m.full*full_need + m.local*local_need + m.linear*linear_need + m.spectral*spectral_need; double collapse=m.collapse_full*(0.25+0.55*(1.0-r.sparse))*max(0.0,m.cost-budget); double uncertainty_gap=max(0.0,r.ood*(1.0-m.uncertainty)+r.entropy*(0.55-m.uncertainty)); double route_miss=max(0.0,0.62*(full_need*(1-m.full)+local_need*(1-m.local)+linear_need*(1-m.linear)+max(0.0,spectral_need)*(1-m.spectral))/2.2 - 0.18*m.uncertainty); double cost=m.cost*(0.72+0.28*log2(r.token_count)/13.0) + 0.03*m.uncertainty; if(m.oracle){raw=0.96; cost=min(0.58,budget+0.03); route_miss=0.02*r.entropy; uncertainty_gap=0.02*r.ood; collapse=0;}
   double quality=max(0.0,min(1.0,raw - 0.22*uncertainty_gap - 0.12*route_miss - collapse)); double over=max(0.0,cost-budget); double posterior_entropy=max(0.0,min(1.0,m.uncertainty*(0.45+0.55*r.entropy)-0.25*m.prior_strength)); double score=(1-quality)+0.52*over+0.22*route_miss+0.18*uncertainty_gap+0.06*cost; cand.push_back({r.name,m.name,bp,quality,cost,over,route_miss,uncertainty_gap,collapse,0,score,posterior_entropy}); }
   double best=1e9; for(auto&x:cand)best=min(best,1-x.quality); for(auto&x:cand){x.regret=max(0.0,(1-x.quality)-best); x.score += 0.12*x.regret;} auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); win[b->method]++; auto bn=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_mechanism")return false; if(b.method=="oracle_mechanism")return true; return a.score<b.score;}); non[bn->method]++; rows.insert(rows.end(),cand.begin(),cand.end()); }
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0029\",\n  \"probe\": \"meta_attention_router\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:win){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Bayesian/cost-prior mechanism routing is worth testing because uncertainty helps OOD and sparse regimes, but always-full remains a hard high-budget anchor.\",\n    \"screen_regret_fields\": [\"cost_frac\", \"budget_over\", \"route_miss\", \"uncertainty_error\", \"collapse_penalty\", \"regret\", \"posterior_entropy\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"budget_pct\": "<<r.budget_pct<<", \"quality\": "<<r.quality<<", \"cost_frac\": "<<r.cost_frac<<", \"budget_over\": "<<r.budget_over<<", \"route_miss\": "<<r.route_miss<<", \"uncertainty_error\": "<<r.uncertainty_error<<", \"collapse_penalty\": "<<r.collapse_penalty<<", \"regret\": "<<r.regret<<", \"posterior_entropy\": "<<r.posterior_entropy<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n"); } f<<"  ]\n}\n"; cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; }
